use vstd::prelude::*;

verus! {

/// Returns a vector of fixed weights determined only by index:
/// - length preserved
/// - endpoints (0 and n-1) have weight 0.5
/// - interior indices have weight 1.0
fn chebweight(x: Vec<f32>) -> (result: Vec<f32>)
    requires
        x.len() > 0,
    ensures
        result.len() == x.len(),
        forall|i: int| 0 <= i < x.len() ==> (
            if i == 0 || i == x.len() - 1 {
                // endpoint weights
                result[i] == 0.5f32
            } else {
                // interior weights
                result[i] == 1.0f32
            }
        ),
{
    let n = x.len();
    let mut result: Vec<f32> = Vec::new();
    let mut i: usize = 0;

    while i < n
        invariant
            n == x.len(),
            result.len() == i,
            forall|j: int| 0 <= j < i as int ==> (
                if j == 0 || j == n as int - 1 {
                    result[j] == 0.5f32
                } else {
                    result[j] == 1.0f32
                }
            ),
    {
        let w = if i == 0 || i + 1 == n { 0.5f32 } else { 1.0f32 };
        result.push(w);
        i += 1;
    }

    result
}

} // verus!